--- index.html
+++ index.html
@@ -19,4 +19,38 @@
 <section class="battle"><div class="status"><div class="status-head"><span class="name">HUMANO</span><span class="level">LV 1</span></div><div class="healthline"><span>HP</span><div class="meter"><div class="fill" id="playerBar"></div></div><span class="numbers" id="playerHpText">20 / 20</span></div><div class="stats-note" id="playerNote">DETERMINACIÓN: ALTA</div></div><div class="status"><div class="status-head"><span class="name">SANS</span><span class="level" id="bossState">HUESOS DUROS</span></div><div class="healthline"><span>HP</span><div class="meter"><div class="fill enemy" id="bossBar"></div></div><span class="numbers" id="bossHpText">1 / 1</span></div><div class="stats-note" id="bossNote">«¿ya terminaste?»</div></div><nav class="actions" aria-label="Acciones de combate"><button class="action" data-action="fight">LUCHAR<span class="key">[ Z ]</span></button><button class="action" data-action="act">ACTUAR<span class="key">[ X ]</span></button><button class="action" data-action="item">OBJETO<span class="key">[ C ]</span></button><button class="action" data-action="mercy">PACIENCIA<span class="key">[ V ]</span></button></nav></section>
 <div class="footer"><span>♥ Un duelo sobre decisiones, no sobre daño.</span><span class="desktop">Usa <span class="kbd">Z X C V</span> · Móvil: toca los botones</span></div>
 </main>
 <script>
+(()=>{
+const cvs=document.getElementById('world'),ctx=cvs.getContext('2d'),scene=document.getElementById('scene');
+const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
+const state={started:false,phase:'intro',hp:20,maxHp:20,boss:1,turn:0,round:0,frame:0,player:{x:0,y:0,inv:0},soul:{x:0,y:0,vx:1,vy:1},bullets:[],skill:0,inventory:2,turnTime:0,toastTimer:0,keys:{},sound:true,shake:0,terminal:false};
+const skills=[{name:'Tajo estrella',icon:'✦',detail:'Rápido · alcance corto',cd:0},{name:'Eco azul',icon:'◈',detail:'Ágil · buen equilibrio',cd:0},{name:'Pulso solar',icon:'☼',detail:'Potente · recarga lenta',cd:0},{name:'Lazo lunar',icon:'✧',detail:'Amplio · preciso',cd:0}];
+let W=900,H=365, last=performance.now();
+function resize(){const r=scene.getBoundingClientRect(),d=Math.min(window.devicePixelRatio||1,2);W=r.width;H=r.height;cvs.width=Math.round(W*d);cvs.height=Math.round(H*d);ctx.setTransform(d,0,0,d,0,0);if(!state.player.x){state.player.x=W/2;state.player.y=H*.75}if(!state.soul.x){state.soul.x=W/2;state.soul.y=H*.43}}
+new ResizeObserver(resize).observe(scene);resize();
+const rand=(a,b)=>a+Math.random()*(b-a),clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
+function say(text,who='SANS',hint=''){ $('#dialogueText').textContent=text;$('#speaker').textContent=who;$('#hint').textContent=hint;$('#portrait').textContent=who==='TÚ'?'♥':'☠';$('#portrait').style.color=who==='TÚ'?'#ff536b':'#fff';$('#speaker').style.color=who==='TÚ'?'#ff6377':'#5eeaff';}
+function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('on');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>e.classList.remove('on'),1800)}
+function updateBars(){$('#playerBar').style.width=`${100*state.hp/state.maxHp}%`;$('#playerHpText').textContent=`${state.hp} / ${state.maxHp}`;$('#bossBar').style.width=`${state.boss>0?100:0}%`;$('#bossHpText').textContent=`${state.boss} / 1`;$('#bossState').textContent=state.boss?'HUESOS DUROS':'DERROTADO';$('#playerNote').textContent=state.inventory?`OBJETOS: ${state.inventory} · TÉ: +6 HP`:'SIN OBJETOS';$('#bossNote').textContent=state.boss?'«¿ya terminaste?»':'…';}
+function showArena(yes){$('#arenaHud').classList.toggle('show',yes);}
+function initArena(){state.player.x=W/2;state.player.y=H*.72;state.soul.x=W/2;state.soul.y=H*.42;state.soul.vx=rand(-1,1);state.soul.vy=rand(-.8,.8);state.bullets=[];state.turnTime=0;state.skill=0;state.phase='player';showArena(true);makeSkills();$('#arenaTitle').textContent='TU TURNO · APUNTA AL ALMA';$('#arenaHelp').textContent='MUÉVETE: WASD / FLECHAS · GOLPEA: ESPACIO / CLIC';say('* El alma de Sans danza en el centro. ¡Acércate y golpea!','TÚ','Cambia de técnica en los laterales. Elige el momento justo.');}
+function makeSkills(){const left=$('#skillsLeft'),right=$('#skillsRight');left.innerHTML='';right.innerHTML='';skills.forEach((s,i)=>{const b=document.createElement('button');b.className='skill'+(i===state.skill?' active':'');b.innerHTML=`<strong>${s.icon} ${s.name}</strong><small>${s.detail}</small>`;b.onclick=()=>selectSkill(i);(i<2?left:right).appendChild(b)});}
+function selectSkill(i){if(state.phase!=='player')return;state.skill=i;$$('.skill').forEach((el,j)=>el.classList.toggle('active',i===j));const lines=['La hoja estelar corta el aire a tu alrededor.','El eco azul sigue los latidos del alma.','El pulso solar amplifica tu siguiente golpe.','El lazo lunar abre una ventana más amplia.'];say(lines[i],'TÚ','¡Acércate al corazón y pulsa ESPACIO!');}
+function playerTurn(){state.round++;initArena();}
+function enemyTurn(){showArena(true);state.phase='enemy';state.turnTime=0;state.bullets=[];state.player.x=W/2;state.player.y=H*.70;$('#arenaTitle').textContent='TURNO DE SANS · SOBREVIVE';$('#arenaHelp').textContent='ESQUIVA LOS HUESOS · WASD / FLECHAS · MÓVIL: ARRASTRA';say(state.round===1?'* Sans chasquea los dedos. El suelo se vuelve azul.':'* Sans bosteza y levanta una ceja.','SANS','Esquiva hasta que termine su turno.');
+const count=6+Math.min(state.round,4);for(let i=0;i<count;i++){setTimeout(()=>{if(state.phase!=='enemy')return;const side=Math.random()<.5?'left':'right';state.bullets.push({x:side==='left'?-10:W+10,y:rand(H*.30,H*.78),vx:side==='left'?rand(2.5,4.0):-rand(2.5,4),vy:rand(-.45,.45),r:rand(7,11),type:'bone',life:260})},i*460)}
+setTimeout(()=>{if(state.phase==='enemy')finishEnemyTurn()},5000+Math.min(state.round,3)*350);
+}
+function finishEnemyTurn(){state.phase='idle';showArena(false);if(state.hp<=0)return;state.turn++;say(state.round===1?'* El aire se calma. Sans parece casi decepcionado.':'* Sans se encoge de hombros. «tu turno, supongo».','SANS');setTimeout(()=>{if(!state.terminal)playerTurn()},1250)}
+function hitPlayer(dmg=2){if(state.player.inv>0||state.phase!=='enemy')return;state.hp=Math.max(0,state.hp-dmg);state.player.inv=45;state.shake=8;updateBars();scene.classList.remove('shake');void scene.offsetWidth;scene.classList.add('shake');if(state.hp<=0){endGame(false);return}toast(`♥ -${dmg} HP`)}
+function attack(){if(state.phase!=='player')return;const s=skills[state.skill],p=state.player,t=state.soul;let dx=p.x-t.x,dy=p.y-t.y;let distance=Math.hypot(dx,dy);let range=[44,58,66,76][state.skill];let angle=Math.atan2(dy,dx),aim=state.facing||0;let angular=Math.abs(Math.atan2(Math.sin(angle-aim),Math.cos(angle-aim)));let chance=distance<range&&angular<([1.25,1.8,2.25,2.7][state.skill]);
+// Generous close-range hitbox; the soul remains evasive, with readable attack windows.
+if(distance<range*.52)chance=true;
+if(chance){state.boss=0;updateBars();state.phase='idle';state.terminal=true;showArena(false);say('* Sans mira su alma, y luego a ti. «heh. buen golpe».','SANS');setTimeout(()=>endGame(true),1450)}else{state.turnTime+=1;toast(distance>range?'¡Más cerca!':'¡Fallaste!');say(distance>range?'* El corazón esquiva tu alcance. ¡Acércate más!':'* El corazón se desliza fuera de tu ataque.','TÚ','El alma se mueve rápido. Prueba otra técnica o espera el momento.');if(state.turnTime>4){state.phase='idle';showArena(false);say('* Sin un golpe certero, Sans recupera el turno.','SANS');setTimeout(()=>{if(!state.terminal)enemyTurn()},900)}}}
+function endGame(win){state.terminal=true;state.phase='end';showArena(false);$('#endTitle').textContent=win?'ALMA EN PAZ':'EL CORREDOR SE OSCURECE';$('#endTitle').style.color=win?'#ffdf66':'#ff708b';$('#endText').textContent=win?'El alma de Sans se apaga como una estrella. No hubo odio, solo un último desafío. El corredor queda en silencio.':'Tu determinación se desvanece. Sans baja la mirada: «quizá en otra línea temporal». Vuelve a intentarlo y aprende su ritmo.';$('#endModal').classList.add('show');say(win?'* La nieve vuelve a caer, suave y silenciosa.':'* Todo se vuelve oscuro…','SANS');}
+function reset(){Object.assign(state,{started:true,phase:'idle',hp:20,boss:1,turn:0,round:0,frame:0,bullets:[],skill:0,inventory:2,turnTime:0,terminal:false});$('#endModal').classList.remove('show');$('#startScreen').style.display='none';updateBars();say('* ...','SANS');setTimeout(playerTurn,550)}
+$$('.action').forEach(b=>b.addEventListener('click',()=>action(b.dataset.action)));function action(a){if(!state.started||state.phase==='end'||state.phase==='player'||state.phase==='enemy')return;
+if(a==='fight'){playerTurn();return}if(a==='act'){say('* Le preguntas a Sans si alguna vez se toma algo en serio. «nope».','TÚ','Se distrae un instante. En tu turno tendrás más tiempo para acertar.');state.turnTime=0;playerTurn();return}
+if(a==='item'){if(!state.inventory){toast('No quedan objetos.');say('* Tu mochila está vacía.','TÚ');return}if(state.hp>=state.maxHp){toast('Ya tienes toda la vida.');say('* No necesitas curarte todavía.','TÚ');return}state.inventory--;state.hp=Math.min(state.maxHp,state.hp+6);updateBars();say('* Bebes un té de canela. Recuperas 6 HP.','TÚ');toast('+6 HP · TÉ DE CANELA');return}
+if(a==='mercy'){if(state.round>=3){say('* Sans deja libre el camino. «ya estuvo bueno, ¿no?»','SANS');toast('¡Sans te deja pasar!');state.terminal=true;setTimeout(()=>endGame(true),1200)}else{say('* Sans no piensa moverse todavía. «te falta calle, humano».','SANS');toast('Sans aún no acepta la paciencia.');}return}}
+$('#beginBtn').onclick=reset;$('#restartBtn').onclick=reset;

