$('#beginBtn').onclick=reset;$('#restartBtn').onclick=reset;
function rounded(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
function heart(x,y,size,color){ctx.save();ctx.translate(x,y);ctx.scale(size/24,size/24);ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(0,8);ctx.bezierCurveTo(-14,-1,-9,-10,0,-4);ctx.bezierCurveTo(9,-10,14,-1,0,8);ctx.fill();ctx.restore()}
function drawBackground(t){
const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#1c1732');sky.addColorStop(.53,'#242440');sky.addColorStop(1,'#0b101e');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
// distant corridor arch, layered with a strong vanishing point
const cx=W*.5,cy=H*.37;ctx.fillStyle='#111324';ctx.beginPath();ctx.moveTo(W*.10,H);ctx.lineTo(W*.26,H*.14);ctx.quadraticCurveTo(cx,H*.00,W*.74,H*.14);ctx.lineTo(W*.90,H);ctx.closePath();ctx.fill();
ctx.strokeStyle='#7561a0';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(W*.13,H);ctx.lineTo(W*.28,H*.17);ctx.quadraticCurveTo(cx,H*.04,W*.72,H*.17);ctx.lineTo(W*.87,H);ctx.stroke();
ctx.strokeStyle='#382e59';ctx.lineWidth=12;ctx.beginPath();ctx.moveTo(W*.06,H);ctx.lineTo(W*.22,H*.12);ctx.quadraticCurveTo(cx,-H*.08,W*.78,H*.12);ctx.lineTo(W*.94,H);ctx.stroke();
// stone blocks on side walls
for(let side of [-1,1]){for(let row=0;row<5;row++){let depth=row/5,y=H*(.18+depth*.82),edge=W*(side<0?.21:.79),outer=W*(side<0?.02:.98),w=(outer-edge)*(.12+depth*.88);let yy=y;ctx.strokeStyle=`rgba(154,133,191,${.22+depth*.2})`;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(side<0?W*.04:W*.96,yy);ctx.lineTo(side<0?edge:edge,yy);ctx.stroke();for(let x=edge;x!==outer;x+=side*w){ctx.strokeStyle='rgba(87,75,120,.35)';ctx.beginPath();ctx.moveTo(x,yy);ctx.lineTo(x,yy+H*.11*(.4+depth));ctx.stroke()}}}
// glowing wall runes & lanterns
for(let i=0;i<5;i++){let yy=H*(.22+i*.14),scale=.22+i*.19;for(let side of [-1,1]){let xx=W*(side<0?.21+.018*i:.79-.018*i);ctx.globalAlpha=.35+Math.sin(t*.002+i)*.12;ctx.fillStyle=i%2?'#50ddff':'#fa62c9';ctx.fillRect(xx-4*scale,yy-9*scale,8*scale,18*scale);ctx.fillStyle='#fff4c4';ctx.fillRect(xx-1.2*scale,yy-5*scale,2.4*scale,7*scale)} }ctx.globalAlpha=1;
// floor with perspective tiles
ctx.fillStyle='#121526';ctx.beginPath();ctx.moveTo(W*.21,H*.58);ctx.lineTo(W*.79,H*.58);ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.closePath();ctx.fill();ctx.strokeStyle='#39314e';ctx.lineWidth=1;for(let i=0;i<9;i++){let q=i/8,y=H*(.60+q*.4);ctx.beginPath();ctx.moveTo(W*.21*(1-q),y);ctx.lineTo(W*(1-.21*(1-q)),y);ctx.stroke()}for(let i=-5;i<=5;i++){ctx.beginPath();ctx.moveTo(cx+i*W*.018,H*.58);ctx.lineTo(cx+i*W*.17,H);ctx.stroke()}
// drifting snow motes
for(let i=0;i<32;i++){let x=(i*173+Math.sin(t*.0006+i*7)*24)%W,y=(i*89+t*(.012+i%3*.006))%(H+10);let sz=(i%3)+1;ctx.fillStyle=i%4?'#dceaff66':'#ffbaff99';ctx.fillRect(x,y,sz,sz)}
// soft glow at the vanishing point
let glow=ctx.createRadialGradient(cx,cy,2,cx,cy,H*.36);glow.addColorStop(0,'#8664d066');glow.addColorStop(1,'#4e39a000');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H);
}
function drawSans(x,y,scale=1){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ctx.imageSmoothingEnabled=false;
// shadow
ctx.fillStyle='#06071188';ctx.fillRect(-28,33,56,8);
// legs and slippers
ctx.fillStyle='#e7e8ef';ctx.fillRect(-15,20,11,15);ctx.fillRect(5,20,11,15);ctx.fillStyle='#80d7f0';ctx.fillRect(-19,31,17,7);ctx.fillRect(3,31,17,7);
// jacket silhouette
ctx.fillStyle='#2d3354';ctx.fillRect(-23,-2,46,29);ctx.fillStyle='#e9e9ef';ctx.fillRect(-16,1,32,21);ctx.fillStyle='#496080';ctx.fillRect(-23,12,10,12);ctx.fillRect(13,12,10,12);
// skull
ctx.fillStyle='#f0f0f0';ctx.fillRect(-21,-37,42,30);ctx.fillRect(-17,-43,34,8);ctx.fillRect(-26,-28,5,13);ctx.fillRect(21,-28,5,13);ctx.fillStyle='#c8c9d3';ctx.fillRect(-18,-10,36,3);
// eye sockets, one glowing
ctx.fillStyle='#10101b';ctx.fillRect(-13,-29,9,10);ctx.fillRect(5,-29,9,10);ctx.fillStyle='#fff';ctx.fillRect(-11,-28,5,7);ctx.fillStyle='#5af1ff';ctx.fillRect(7,-27,4,6);ctx.fillStyle='#fff';ctx.fillRect(8,-27,2,2);
// grin
ctx.fillStyle='#343342';ctx.fillRect(-10,-13,20,2);ctx.fillStyle='#fff';for(let i=-7;i<8;i+=5)ctx.fillRect(i,-12,2,2);
ctx.restore()}
function drawHuman(x,y,scale=1){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ctx.fillStyle='#07081088';ctx.fillRect(-15,12,30,5);ctx.fillStyle='#b9e8d8';ctx.fillRect(-7,-17,14,10);ctx.fillStyle='#442a5c';ctx.fillRect(-9,-7,18,14);ctx.fillStyle='#62d7c8';ctx.fillRect(-10,6,8,11);ctx.fillRect(2,6,8,11);ctx.fillStyle='#ffe18a';ctx.fillRect(-10,-15,4,2);ctx.restore()}
function arenaRect(){const w=Math.min(W*.53,510),h=Math.min(H*.58,220),x=(W-w)/2,y=H*.28;return{x,y,w,h}}
function bone(b){ctx.save();ctx.translate(b.x,b.y);ctx.rotate(Math.atan2(b.vy,b.vx));ctx.fillStyle='#f5f4ee';ctx.fillRect(-b.r,-b.r*.32,b.r*2,b.r*.64);ctx.beginPath();ctx.arc(-b.r,0,b.r*.64,0,Math.PI*2);ctx.arc(b.r,0,b.r*.64,0,Math.PI*2);ctx.fill();ctx.restore()}
function drawArena(){let a=arenaRect();ctx.fillStyle='#06060b';ctx.fillRect(a.x,a.y,a.w,a.h);ctx.strokeStyle='#f1edfc';ctx.lineWidth=3;ctx.strokeRect(a.x,a.y,a.w,a.h);ctx.strokeStyle='#6d6981';ctx.lineWidth=1;ctx.strokeRect(a.x+4,a.y+4,a.w-8,a.h-8);
// target soul — cyan halo and bright red heart
let pulse=1+Math.sin(state.frame*.12)*.15;ctx.globalAlpha=.25;ctx.fillStyle='#ff365e';ctx.beginPath();ctx.arc(state.soul.x,state.soul.y,19*pulse,0,7);ctx.fill();ctx.globalAlpha=1;heart(state.soul.x,state.soul.y,19,'#ff334f');
for(const b of state.bullets)bone(b);
if(state.phase==='enemy')drawHuman(state.player.x,state.player.y,1.05);else{let c=state.player.inv>0&&Math.floor(state.frame/4)%2?'#fff': '#ffdf46';heart(state.player.x,state.player.y,24,c);}
// menu skill lines hints
}
function draw(t){ctx.clearRect(0,0,W,H);drawBackground(t);drawSans(W*.5,H*.62,Math.min(1.3,W/700));if(state.phase==='player'||state.phase==='enemy')drawArena();if(state.phase==='idle'&&state.started){drawHuman(W*.43,H*.79,.85);ctx.fillStyle='#fff';ctx.font='12px monospace';ctx.textAlign='center';ctx.fillText('ELIGE TU SIGUIENTE ACCIÓN',W/2,H*.91)} }

