function draw(t){ctx.clearRect(0,0,W,H);drawBackground(t);drawSans(W*.5,H*.62,Math.min(1.3,W/700));if(state.phase==='player'||state.phase==='enemy')drawArena();if(state.phase==='idle'&&state.started){drawHuman(W*.43,H*.79,.85);ctx.fillStyle='#fff';ctx.font='12px monospace';ctx.textAlign='center';ctx.fillText('ELIGE TU SIGUIENTE ACCIÓN',W/2,H*.91)} }
function positionFromEvent(e){const r=cvs.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}
let pointerDown=false; cvs.addEventListener('pointerdown',e=>{if(state.phase!=='player'&&state.phase!=='enemy')return;pointerDown=true;cvs.setPointerCapture(e.pointerId);const p=positionFromEvent(e);state.player.x=p.x;state.player.y=p.y;if(state.phase==='player')attack();});
cvs.addEventListener('pointermove',e=>{if(!pointerDown||!(state.phase==='player'||state.phase==='enemy'))return;const p=positionFromEvent(e);movePlayerTo(p.x,p.y)});cvs.addEventListener('pointerup',()=>pointerDown=false);cvs.addEventListener('pointercancel',()=>pointerDown=false);
function movePlayerTo(x,y){const a=arenaRect(),ox=state.player.x,oy=state.player.y;state.player.x=clamp(x,a.x+13,a.x+a.w-13);state.player.y=clamp(y,a.y+13,a.y+a.h-13);if(Math.hypot(state.player.x-ox,state.player.y-oy)>1)state.facing=Math.atan2(state.player.y-oy,state.player.x-ox)}
window.addEventListener('keydown',e=>{const key=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(key))e.preventDefault();state.keys[key]=true;if(e.repeat)return;
if(state.phase==='player'){if(key===' '||key==='z'||key==='enter')attack();else if(key==='1'||key==='2'||key==='3'||key==='4')selectSkill(+key-1);return}
if(state.phase==='enemy')return;if(key==='z'||key==='enter')action('fight');else if(key==='x')action('act');else if(key==='c')action('item');else if(key==='v')action('mercy')});window.addEventListener('keyup',e=>state.keys[e.key.toLowerCase()]=false);
function moveByKeys(){if(state.phase!=='player'&&state.phase!=='enemy')return;let x=0,y=0,k=state.keys;if(k.arrowleft||k.a)x--;if(k.arrowright||k.d)x++;if(k.arrowup||k.w)y--;if(k.arrowdown||k.s)y++;if(!x&&!y)return;const d=Math.hypot(x,y),speed=state.phase==='player'?3.15:3.7;const oldx=state.player.x,oldy=state.player.y;movePlayerTo(state.player.x+x/d*speed,state.player.y+y/d*speed);state.facing=Math.atan2(y,x);}
function update(dt){state.frame+=dt*60;if(state.player.inv>0)state.player.inv-=dt*60;moveByKeys();if(state.phase==='player'){
state.turnTime+=dt;const a=arenaRect(),s=state.soul,margin=22;s.x+=s.vx*dt*60;s.y+=s.vy*dt*60;if(s.x<a.x+margin||s.x>a.x+a.w-margin)s.vx*=-1;if(s.y<a.y+margin||s.y>a.y+a.h-margin)s.vy*=-1;
// occasional, telegraphed evasive feint
if(Math.floor(state.frame)%155===0){s.vx*=1.24;s.vy*=1.24;setTimeout(()=>{if(state.phase==='player'){s.vx*=.81;s.vy*=.81}},430)}
if(state.turnTime>13){state.phase='idle';showArena(false);say('* Te cansas. Sans se prepara para contraatacar.','SANS');setTimeout(()=>{if(!state.terminal)enemyTurn()},800)}
}else if(state.phase==='enemy'){
const a=arenaRect();state.bullets.forEach(b=>{b.x+=b.vx*dt*60;b.y+=b.vy*dt*60;b.life-=dt*60;const d=Math.hypot(b.x-state.player.x,b.y-state.player.y);if(d<b.r+10){hitPlayer(2);b.life=0}});state.bullets=state.bullets.filter(b=>b.life>0&&b.x>-35&&b.x<W+35);
if(state.round%2===0&&Math.floor(state.turnTime*3)%23===0){/* rhythmic pressure, no surprise damage */}
state.turnTime+=dt;
}}
function loop(now){const dt=Math.min((now-last)/1000,.04);last=now;update(dt);draw(now);requestAnimationFrame(loop)}requestAnimationFrame(loop);
$('#soundBtn').onclick=()=>{state.sound=!state.sound;$('#soundBtn').textContent=state.sound?'♫ ON':'♫ OFF';toast(state.sound?'Sonido activado':'Sonido desactivado')};
$$('.action').forEach(b=>b.addEventListener('focus',()=>{}));updateBars();
})();
</script>
</body>
</html>

